// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(address caller, uint256 collectAmt, uint256 depositAmt) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmt > 0);
        vm.assume(address(this).balance >= depositAmt);
        uint balBeforeCollect = address(c).balance;
        try c.Collect(collectAmt) {} catch { return; }
        uint balAfterCollect = address(c).balance;
        try c.Deposit{value: depositAmt}() {} catch { return; }
        uint256 newRecorded;
        try c.balances(address(this)) returns (uint256 __r) { newRecorded = __r; } catch { return; }
        assertTrue(newRecorded >= depositAmt + (balAfterCollect - balBeforeCollect - (address(c).balance - balAfterCollect)) * 0 + 0);
    }

    function testFuzz_run(address caller, uint256 collectAmt, uint256 depositAmt) public {
        _run(caller, collectAmt, depositAmt);
    }

    receive() external payable { }
}
